def gen(rng):
    def fmt(qs):
        return str(len(qs)) + '\n' + '\n'.join(f'{x} {n}' for x, n in qs)
    tests = [fmt([(0, 16)]), fmt([(1, 16)]), fmt([(16, 16)]), fmt([(17, 16)]), fmt([(10**15, 10**9)]),
             fmt([(10**15 - 1, 10**9), (10**15, 1), (0, 10**9)]), fmt([(5, 1), (5, 5), (5, 6), (5, 4)])]
    for _ in range(8):
        qs = []
        for _ in range(rng.randint(1, 12)):
            n = rng.choice([16, 16, 8, 32, 4, 2, 1, rng.randint(1, 40)])
            qs.append((rng.randint(0, 200), n))
        tests.append(fmt(qs))
    for _ in range(3):
        tests.append(fmt([(rng.randint(0, 300), 16) for _ in range(rng.randint(5, 12))]))
    # large
    tests.append(fmt([(rng.randint(0, 10**15), rng.choice([16, 2**rng.randint(0, 29), rng.randint(1, 10**9)])) for _ in range(50000)]))
    tests.append(fmt([(10**15 - rng.randint(0, 10**6), rng.randint(1, 10**9)) for _ in range(50000)]))
    tests.append(fmt([(rng.randint(0, 10**15), 16) for _ in range(50000)]))
    return tests
